      convenio_nombre: prepareData.convenio_nombre,
      operation: 'skipped',
      validation: prepareData.validation || { stats: {}, is_valid: false },
      claude_usage: prepareData.claude_usage
    }
  }];
}

const insertData = $input.first().json;
const convenioNombre = prepareData.convenio_nombre;
const validation = prepareData.validation || { stats: {}, is_valid: false };
const claudeUsage = prepareData.claude_usage;
const convenioUuid = prepareData.convenio_uuid;

// Check si el nodo HTTP anterior falló
if (insertData.error) {
  console.log('⚠ Error al insertar perfil: ' + (insertData.error.message || JSON.stringify(insertData.error)));
  throw new Error('Error al guardar perfil en Supabase: ' + (insertData.error.message || ''));
}

const savedData = insertData;
const savedPerfil = Array.isArray(savedData) ? savedData[0] : savedData;

console.log(`✓ Perfil guardado correctamente (upsert)`);
console.log(`  Categorías: ${validation?.stats?.categorias || 0} | Complementos: ${validation?.stats?.complementos || 0}`);

return [{
  json: {
    perfil_id: savedPerfil.id,
    convenio_id: convenioUuid,
    convenio_nombre: convenioNombre,
    operation: 'upserted',
    validation: validation,
    claude_usage: claudeUsage
  }
}];
